import{_ as e,c as t,o as c,b2 as n}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"C7Switch 开关","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-switch.md","filePath":"docs/frontend/components/通用组件/c7-switch.md"}'),s={name:"docs/frontend/components/通用组件/c7-switch.md"};function r(d,o,a,g,i,l){return c(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="c7switch-开关" tabindex="-1">C7Switch 开关 <a class="header-anchor vp-link" href="#c7switch-开关" aria-label="Permalink to &quot;C7Switch 开关&quot;">​</a></h1><p>在 <strong><code>ElSwitch</code></strong> 上封装 <strong>切换前校验</strong>、<strong>二次确认</strong>、<strong>可选异步提交</strong>（失败保持原值）与 <strong>字典优先</strong> 的内外文案映射。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7Switch/index.vue</code><br><strong>Dev 页</strong>：开发服务器启动后访问 <code>/dev/c7-switch-e2e</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong>值体系</strong>：<strong><code>v-model</code></strong>（<strong><code>modelValue</code></strong>）与 <strong><code>activeValue</code> / <code>inactiveValue</code></strong>。</li><li><strong>文案</strong>：<strong><code>dictList</code></strong> 与 <strong><code>activeValue</code>/<code>inactiveValue</code></strong> 使用 <strong><code>===</code></strong> 匹配；<strong>字典命中优先</strong>，否则 <strong><code>activeText</code> / <code>inactiveText</code></strong> 兜底。</li><li><strong>流水线</strong>：<strong><code>beforeChange(newVal)</code></strong> → <strong>确认</strong>（<strong><code>confirmFn</code> 优先</strong>；否则 <strong><code>confirmMessage</code>（trim 非空）</strong> 弹 <strong><code>ElMessageBox.confirm</code></strong>）→ 可选 <strong><code>asyncChange(newVal)</code></strong>（<strong>loading</strong>；失败 <strong>不</strong>更新值、<strong>不</strong> <code>emit(&#39;cancel&#39;)</code>）→ 可选 <strong><code>afterChange</code></strong>（<strong>无 <code>asyncChange</code> 的同步成功也会调用</strong>）。</li><li><strong>静默</strong>：<strong><code>beforeChange</code> 返回严格 <code>false</code></strong> 时 <strong>完全静默</strong>（<strong>不</strong> <code>emit(&#39;cancel&#39;)</code>）。</li><li><strong>颜色</strong>：<strong><code>activeColor</code> / <code>inactiveColor</code></strong> 映射为 <strong><code>--el-switch-on-color</code> / <code>--el-switch-off-color</code></strong>（Element Plus 2.10+）。</li><li><strong>事件</strong>：成功提交时 <strong>先</strong> <strong><code>update:modelValue</code></strong> <strong>再</strong> <strong><code>change(newVal, oldVal)</code></strong>；中止确认 <strong>emit <code>cancel</code></strong>。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p>在 <code>main.js</code> 已调用 <code>installPackages(app)</code> 时，模板中可直接使用 <code>&lt;c7-switch /&gt;</code>（或 <code>&lt;C7Switch /&gt;</code>）。</p><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><p>OpenSpec 变更：<code>openspec/changes/ui-c7-switch/specs/ui-c7-switch/spec.md</code></p>',9)])])}const m=e(s,[["render",r]]);export{p as __pageData,m as default};
